<?php
class Commerce {
 static function rounded(int $amount,int $basis):int{return (int)bcdiv(bcadd(bcmul((string)$amount,(string)$basis,0),'5000',0),'10000',0);}
 static function proportion(int $amount,int $part,int $whole):int{return $whole===0?0:(int)bcdiv(bcmul((string)$amount,(string)$part,0),(string)$whole,0);}
 static function quote(array $cart,array $d=[],bool $lock=false):array {
  if(!$cart)fail('Your cart is empty.');if(count($cart)>100)fail('Too many cart lines.');$lines=[];$subtotal=0;ksort($cart,SORT_NUMERIC);
  foreach($cart as $id=>$quantity){$qty=integer($quantity,1,999);$v=Catalog::sellable((int)$id,$lock);$price=(int)($v['sale_price']??$v['price']);$gross=$price*$qty;
   if(enabled('inventory')&&$v['track_stock']&&$v['availability']==='normal'&&$qty>$v['physical']-$v['reserved'])fail($v['name'].' has insufficient available stock.');
   if($v['availability']==='preorder'&&$v['max_preorder']!==null){$used=(int)one("SELECT COALESCE(SUM(oi.quantity),0) n FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE oi.variant_id=? AND o.status NOT IN ('cancelled','completed')",[$id])['n'];if($qty+$used>$v['max_preorder'])fail('Pre-order limit reached for '.$v['name']);}
   $lines[]=['variant'=>$v,'quantity'=>$qty,'price'=>$price,'gross'=>$gross,'discount'=>0];$subtotal+=$gross;
  }
  $coupon=null;$discount=0;$eligible=[];$eligibleTotal=0;
  if(!empty($d['coupon'])){module('coupons');$coupon=one('SELECT * FROM coupons WHERE code=? AND enabled=1 AND starts_at<=CURRENT_DATE AND ends_at>=CURRENT_DATE'.($lock?' FOR UPDATE':''),[strtoupper(trim($d['coupon']))]);if(!$coupon||$subtotal<$coupon['minimum'])fail('Coupon is invalid or minimum spend is not met.');$used=(int)one('SELECT COUNT(*) n FROM coupon_redemptions WHERE coupon_id=?',[$coupon['id']])['n'];if($coupon['usage_limit']!==null&&$used>=$coupon['usage_limit'])fail('Coupon usage limit reached.');foreach($lines as $i=>$line)if((!$coupon['product_id']||$coupon['product_id']==$line['variant']['product_id'])&&(!$coupon['category_id']||in_array((int)$line['variant']['category_id'],Catalog::descendants((int)$coupon['category_id']),true))){$eligible[]=$i;$eligibleTotal+=$line['gross'];}if(!$eligibleTotal)fail('Coupon does not apply to these products.');$discount=min($eligibleTotal,$coupon['type']==='percentage'?self::rounded($eligibleTotal,(int)$coupon['value']):(int)$coupon['value']);}
  $left=$discount;$remainingBase=$eligibleTotal;foreach($eligible as $i){$share=$remainingBase===$lines[$i]['gross']?$left:self::proportion($left,$lines[$i]['gross'],$remainingBase);$lines[$i]['discount']=$share;$left-=$share;$remainingBase-=$lines[$i]['gross'];}
  $tax=0;$due=0;$rate=(int)setting('tax_basis_points',0);foreach($lines as &$line){$v=$line['variant'];$net=$line['gross']-$line['discount'];$line['tax']=self::rounded($net,$rate);$line['total']=$net+$line['tax'];$deposit=$net;
   if($v['availability']==='preorder'){$deposit=0;if(enabled('advances'))$deposit=match($v['deposit_type']){'percentage'=>self::rounded($net,(int)$v['deposit_value']),'fixed'=>min($net,(int)$v['deposit_value']*$line['quantity']),default=>0};}
   $line['due_now']=min($net,$deposit)+$line['tax'];$tax+=$line['tax'];$due+=$line['due_now'];
  }unset($line);
  $shipping=0;$delivery=$d['delivery']??'collection';if($delivery==='delivery'){module('delivery');$zones=setting('delivery_zones',[]);$zone=$d['zone']??'';if(!array_key_exists($zone,$zones))fail('Select a delivery zone.');$shipping=(int)$zones[$zone];$threshold=(int)setting('free_shipping_threshold',0);if($threshold>0&&$subtotal-$discount>=$threshold)$shipping=0;}elseif($delivery!=='collection')fail('Invalid delivery method.');
  return ['lines'=>$lines,'subtotal'=>$subtotal,'discount'=>$discount,'tax'=>$tax,'shipping'=>$shipping,'total'=>$subtotal-$discount+$tax+$shipping,'due_now'=>$due+$shipping,'remaining'=>$subtotal-$discount+$tax-$due,'coupon'=>$coupon,'count'=>array_sum($cart)];
 }
 static function publicQuote(array $cart,array $d=[]):array{$r=self::quote($cart,$d);foreach($r['lines'] as &$l){$v=$l['variant'];$l['variant']=array_intersect_key($v,array_flip(['id','name','label','sku','image','availability','expected_date','deposit_type','deposit_value','unit']));}unset($l);unset($r['coupon']);return $r;}
 static function checkout(array $cart,array $d):array {
  foreach(['name','email','phone','billing_address','payment_method','idempotency_key'] as $key)if(empty($d[$key]))fail('Complete the required checkout fields.',422,[$key=>'Required']);if(!filter_var($d['email'],FILTER_VALIDATE_EMAIL))fail('Enter a valid email.',422,['email'=>'Invalid email']);if(empty($d['policy']))fail('Please accept the store policy.');if(!in_array($d['payment_method'],['cash','bank_transfer','external_card','other'],true))fail('Invalid payment method.');if(strlen($d['idempotency_key'])<16||strlen($d['idempotency_key'])>100)fail('Invalid checkout key.');
  self::expire();$fingerprint=hash('sha256',json_encode([$cart,$d['name'],$d['email'],$d['billing_address'],$d['delivery']??'collection',$d['zone']??'',$d['coupon']??'',$_SESSION['customer_id']??null]));
  return tx(function()use($cart,$d,$fingerprint){$existing=one('SELECT * FROM orders WHERE checkout_key=? FOR UPDATE',[$d['idempotency_key']]);if($existing){if(!hash_equals($existing['request_hash'],$fingerprint))fail('Checkout key was reused with different details.',409);return ['id'=>$existing['id'],'number'=>$existing['number'],'redirect'=>url('order',['id'=>$existing['id']])];}
   $r=self::quote($cart,$d,true);$token=bin2hex(random_bytes(32));$snap=[];foreach(['store_name','legal_name','address','phone','email','logo','currency_symbol','invoice_note','bank_details'] as $key)$snap[$key]=setting($key);
   q('INSERT INTO orders(checkout_key,request_hash,access_hash,customer_id,name,email,phone,billing_address,shipping_address,delivery,zone,notes,currency,subtotal,discount,tax,shipping,total,due_now,store_snapshot) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$d['idempotency_key'],$fingerprint,hash('sha256',$token),enabled('accounts')?($_SESSION['customer_id']??null):null,$d['name'],$d['email'],$d['phone'],$d['billing_address'],$d['shipping_address']??$d['billing_address'],$d['delivery']??'collection',$d['zone']??'',$d['notes']??'',setting('currency','LKR'),$r['subtotal'],$r['discount'],$r['tax'],$r['shipping'],$r['total'],$r['due_now'],json_encode($snap)]);$id=(int)db()->lastInsertId();$number='ORD-'.date('Y').'-'.str_pad((string)$id,6,'0',STR_PAD_LEFT);q('UPDATE orders SET number=? WHERE id=?',[$number,$id]);
   foreach($r['lines'] as $l){$v=$l['variant'];q('INSERT INTO order_items(order_id,product_id,variant_id,name,sku,variant_label,category_name,brand_name,quantity,unit_price,unit_cost,discount,tax,total,due_now,availability,deposit_type,deposit_value,expected_date,stock_tracked) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$v['product_id'],$v['id'],$v['name'],$v['sku'],$v['label'],$v['category'],$v['brand']??'',$l['quantity'],$l['price'],$v['cost'],$l['discount'],$l['tax'],$l['total'],$l['due_now'],$v['availability'],$v['deposit_type'],$v['deposit_value'],$v['expected_date'],(int)(enabled('inventory')&&$v['track_stock'])]);$item=(int)db()->lastInsertId();if(enabled('inventory')&&$v['track_stock']&&$v['availability']==='normal'){q('UPDATE inventory_balances SET reserved=reserved+? WHERE variant_id=?',[$l['quantity'],$v['id']]);$minutes=integer(setting('reservation_minutes',1440),5,43200);q("INSERT INTO inventory_reservations(order_item_id,variant_id,quantity,expires_at) VALUES(?,?,?,DATE_ADD(NOW(),INTERVAL $minutes MINUTE))",[$item,$v['id'],$l['quantity']]);self::movement((int)$v['id'],$l['quantity'],'reserve',$id,'Checkout reservation');}}
   if($r['coupon'])q('INSERT INTO coupon_redemptions(coupon_id,order_id) VALUES(?,?)',[$r['coupon']['id'],$id]);self::history($id,'pending','Order created; manual payment is not verified.');if($r['due_now']>0)self::recordPayment($id,$r['due_now'],$d['payment_method'],$d['reference']??'','checkout-'.$d['idempotency_key'],null);self::invoice($id);$_SESSION['order_access'][$id]=$token;return ['id'=>$id,'number'=>$number,'access_token'=>$token,'redirect'=>url('order',['id'=>$id,'token'=>$token])];
  });
 }
 static function ledger(int $id):array{$paid=(int)one("SELECT COALESCE(SUM(amount),0) n FROM payments WHERE order_id=? AND status='confirmed'",[$id])['n'];$refunded=(int)one('SELECT COALESCE(SUM(amount),0) n FROM refunds WHERE order_id=?',[$id])['n'];$o=one('SELECT total,due_now,status FROM orders WHERE id=?',[$id]);if(!$o)fail('Order not found.',404);$out=max(0,(int)$o['total']-$paid);return ['paid'=>$paid,'refunded'=>$refunded,'net_collections'=>$paid-$refunded,'outstanding'=>$o['status']==='cancelled'?0:$out,'payment_status'=>$paid>=(int)$o['total']?'Fully paid':($paid>=(int)$o['due_now']&&$paid>0?'Advance paid':($paid>0?'Partially paid':'Advance pending'))];}
 static function access(int $id,string $token=''):array {$o=one('SELECT * FROM orders WHERE id=?',[$id]);if(!$o)fail('Order not found.',404);$own=isset($_SESSION['customer_id'])&&$o['customer_id']!==null&&(int)$o['customer_id']===(int)$_SESSION['customer_id'];$token=$token?:($_SESSION['order_access'][$id]??'');if(!allowed('orders.view')&&!$own&&!($token&&hash_equals($o['access_hash'],hash('sha256',$token))))fail('You cannot access this order.',403);if($token)$_SESSION['order_access'][$id]=$token;unset($o['access_hash'],$o['request_hash'],$o['checkout_key']);if(!allowed('orders.view'))unset($o['internal_notes']);return $o;}
 static function detail(int $id,string $token=''):array {$o=self::access($id,$token);$o['items']=all('SELECT * FROM order_items WHERE order_id=?',[$id]);foreach($o['items'] as &$i)if(!allowed('costs'))unset($i['unit_cost']);unset($i);$o['payments']=all('SELECT id,amount,currency,method,reference,status,created_at,verified_at FROM payments WHERE order_id=? ORDER BY id',[$id]);$o['refunds']=all('SELECT amount,reason,reference,created_at FROM refunds WHERE order_id=?',[$id]);$o['history']=all('SELECT h.*,s.name staff_name FROM order_status_history h LEFT JOIN staff_users s ON s.id=h.staff_id WHERE order_id=? ORDER BY h.id',[$id]);return $o+self::ledger($id);}
 static function recordPayment(int $id,int $amount,string $method,string $ref,string $key,?int $staffId,string $notes=''):int{return tx(function()use($id,$amount,$method,$ref,$key,$staffId,$notes){$o=one('SELECT * FROM orders WHERE id=? FOR UPDATE',[$id]);if(!$o||$o['status']==='cancelled')fail('Cannot accept payment for this order.');$old=one('SELECT * FROM payments WHERE idempotency_key=?',[$key]);if($old){if($old['order_id']!=$id||$old['amount']!=$amount||$old['method']!==$method)fail('Payment key conflict.',409);return (int)$old['id'];}if($amount<=0||$amount>self::ledger($id)['outstanding'])fail('Payment must be positive and cannot exceed the outstanding balance.');if(!in_array($method,['cash','bank_transfer','external_card','other'],true))fail('Invalid payment method.');if(strlen($key)<16||strlen($key)>100)fail('Invalid payment key.');if($ref!==''&&one("SELECT id FROM payments WHERE order_id=? AND method=? AND reference=? AND status<>'rejected'",[$id,$method,$ref]))fail('This payment reference is already recorded.');q('INSERT INTO payments(order_id,idempotency_key,amount,currency,method,reference,notes,recorded_by) VALUES(?,?,?,?,?,?,?,?)',[$id,$key,$amount,$o['currency'],$method,$ref,$notes,$staffId]);$pid=(int)db()->lastInsertId();q('INSERT INTO payment_events(payment_id,event,staff_id) VALUES(?,?,?)',[$pid,'recorded',$staffId]);return $pid;});}
 static function verifyPayment(int $pid,bool $confirm,int $sid):void{tx(function()use($pid,$confirm,$sid){$p=one('SELECT * FROM payments WHERE id=?',[$pid]);if(!$p)fail('Payment not found.',404);$o=one('SELECT * FROM orders WHERE id=? FOR UPDATE',[$p['order_id']]);$p=one('SELECT * FROM payments WHERE id=? FOR UPDATE',[$pid]);$state=$confirm?'confirmed':'rejected';if($p['status']===$state)return;if($p['status']!=='pending')fail('Verified financial records are immutable.');if($confirm&&($o['status']==='cancelled'||$p['amount']>self::ledger((int)$o['id'])['outstanding']))fail('This payment would overpay a cancelled or settled order.');q('UPDATE payments SET status=?,verified_by=?,verified_at=NOW() WHERE id=?',[$state,$sid,$pid]);q('INSERT INTO payment_events(payment_id,event,staff_id) VALUES(?,?,?)',[$pid,$state,$sid]);if($confirm)q("UPDATE inventory_reservations r JOIN order_items i ON i.id=r.order_item_id SET r.expires_at=NULL WHERE i.order_id=? AND r.state='reserved'",[$o['id']]);audit('payment.'.$state,'payment',$pid);});}
 static function refund(int $id,array $d,int $sid):void{tx(function()use($id,$d,$sid){$o=one('SELECT * FROM orders WHERE id=? FOR UPDATE',[$id]);if(!$o)fail('Order not found.',404);$amount=cents($d['amount']);$merch=cents($d['merchandise_amount']??$d['amount']);$cost=cents($d['cost_reversal']??'0');$old=one('SELECT * FROM refunds WHERE idempotency_key=?',[$d['idempotency_key']]);if($old){if($old['order_id']!=$id||$old['amount']!=$amount)fail('Refund key conflict.',409);return;}$l=self::ledger($id);$previous=one('SELECT COALESCE(SUM(merchandise_amount),0) merch,COALESCE(SUM(cost_reversal),0) costs FROM refunds WHERE order_id=?',[$id]);$costs=(int)one('SELECT SUM(unit_cost*quantity) n FROM order_items WHERE order_id=?',[$id])['n'];if($amount<=0||$amount>$l['paid']-$l['refunded']||$merch>$amount||$merch+$previous['merch']>$o['subtotal']-$o['discount']||$cost+$previous['costs']>$costs)fail('Refund exceeds eligible payment, merchandise, or cost amounts.');if(empty(trim($d['reason']??''))||empty(trim($d['reference']??'')))fail('Reason and external refund reference are required.');q('INSERT INTO refunds(order_id,idempotency_key,amount,merchandise_amount,cost_reversal,reason,reference,staff_id) VALUES(?,?,?,?,?,?,?,?)',[$id,$d['idempotency_key'],$amount,$merch,$cost,$d['reason'],$d['reference'],$sid]);q('UPDATE orders SET refund_state=? WHERE id=?',[$l['refunded']+$amount>=$l['paid']?'full':'partial',$id]);audit('refund.recorded','order',$id,['amount'=>$amount]);});}
 static function movement(int $vid,int $qty,string $type,?int $order,string $reason,?int $purchase=null):void{q('INSERT INTO inventory_movements(variant_id,quantity,type,order_id,purchase_id,staff_id,reason) VALUES(?,?,?,?,?,?,?)',[$vid,$qty,$type,$order,$purchase,$_SESSION['staff']['id']??null,$reason]);}
 static function history(int $id,string $state,string $notes='',?int $item=null):void{q('INSERT INTO order_status_history(order_id,item_id,status,notes,staff_id) VALUES(?,?,?,?,?)',[$id,$item,$state,$notes,$_SESSION['staff']['id']??null]);}
 static function progress(int $item,string $next,string $notes=''):void{module('preorders');tx(function()use($item,$next,$notes){$i=one("SELECT * FROM order_items WHERE id=? AND availability='preorder' FOR UPDATE",[$item]);if(!$i)fail('Pre-order line not found.',404);if($i['progress']===$next)return;$o=one('SELECT status FROM orders WHERE id=?',[$i['order_id']]);$flow=['awaiting confirmation'=>['confirmed'],'confirmed'=>['awaiting stock'],'awaiting stock'=>['stock arrived'],'stock arrived'=>['ready for collection','ready for delivery'],'ready for collection'=>['completed'],'ready for delivery'=>['completed'],'completed'=>[],'cancelled'=>[]];if($next==='cancelled'){if($o['status']!=='cancelled')fail('Cancel the order to release reservations first.');}elseif(!in_array($next,$flow[$i['progress']]??[],true))fail('Invalid pre-order progress transition.');if($next==='completed'&&$o['status']!=='completed')fail('Complete the order after payment and fulfillment first.');if(in_array($next,['stock arrived','ready for collection','ready for delivery'],true)&&$i['stock_tracked']&&!one("SELECT id FROM inventory_reservations WHERE order_item_id=? AND state='reserved'",[$item]))fail('Allocate received stock first.');q('UPDATE order_items SET progress=? WHERE id=?',[$next,$item]);self::history((int)$i['order_id'],$next,$notes,$item);});}
 static function release(int $id):void{$rows=all("SELECT r.* FROM inventory_reservations r JOIN order_items i ON i.id=r.order_item_id WHERE i.order_id=? AND r.state='reserved' ORDER BY r.variant_id FOR UPDATE",[$id]);foreach($rows as $r){q('UPDATE inventory_balances SET reserved=reserved-? WHERE variant_id=?',[$r['quantity'],$r['variant_id']]);q("UPDATE inventory_reservations SET state='released' WHERE id=?",[$r['id']]);self::movement((int)$r['variant_id'],-(int)$r['quantity'],'release',$id,'Order cancelled or reservation expired');}}
 static function expire():int{$ids=all("SELECT DISTINCT i.order_id FROM inventory_reservations r JOIN order_items i ON i.id=r.order_item_id WHERE r.state='reserved' AND r.expires_at<NOW() LIMIT 100");$n=0;foreach($ids as $r)tx(function()use($r,&$n){$o=one('SELECT * FROM orders WHERE id=? FOR UPDATE',[$r['order_id']]);if($o['status']==='cancelled')return;$expired=one("SELECT r.id FROM inventory_reservations r JOIN order_items i ON i.id=r.order_item_id WHERE i.order_id=? AND r.state='reserved' AND r.expires_at<NOW()",[$o['id']]);if(!$expired||self::ledger((int)$o['id'])['paid']>0)return;self::release((int)$o['id']);q("UPDATE orders SET status='cancelled' WHERE id=?",[$o['id']]);q("UPDATE payments SET status='rejected' WHERE order_id=? AND status='pending'",[$o['id']]);self::history((int)$o['id'],'cancelled','Unpaid reservation expired');$n++;});return $n;}
 static function status(int $id,string $next,string $notes=''):void{self::expire();tx(function()use($id,$next,$notes){$o=one('SELECT * FROM orders WHERE id=? FOR UPDATE',[$id]);if(!$o)fail('Order not found.',404);if($o['status']===$next)return;$flow=['pending'=>['confirmed','cancelled'],'confirmed'=>['processing','cancelled'],'processing'=>['ready','cancelled'],'ready'=>['shipped','completed','cancelled'],'shipped'=>['delivered'],'delivered'=>['completed'],'completed'=>[],'cancelled'=>[]];if(!in_array($next,$flow[$o['status']]??[],true))fail('Invalid order status transition.');if($next==='cancelled'){self::release($id);q("UPDATE payments SET status='rejected' WHERE order_id=? AND status='pending'",[$id]);}if(in_array($next,['shipped','completed'],true)&&!in_array($o['status'],['shipped','delivered'],true)){if(self::ledger($id)['outstanding']>0)fail('Full payment is required before fulfillment.');$items=all('SELECT i.*,v.track_stock FROM order_items i JOIN product_variants v ON v.id=i.variant_id WHERE order_id=? ORDER BY variant_id',[$id]);foreach($items as $i){$r=one('SELECT * FROM inventory_reservations WHERE order_item_id=? FOR UPDATE',[$i['id']]);if($i['stock_tracked']&&(!$r||$r['state']!=='reserved'))fail('Allocate stock for every line before fulfillment.');if($r&&$r['state']==='reserved'){q('UPDATE inventory_balances SET physical=physical-?,reserved=reserved-? WHERE variant_id=?',[$i['quantity'],$i['quantity'],$i['variant_id']]);q("UPDATE inventory_reservations SET state='consumed' WHERE id=?",[$r['id']]);self::movement((int)$i['variant_id'],-(int)$i['quantity'],'sale',$id,'Fulfilled once');}}}q('UPDATE orders SET status=? WHERE id=?',[$next,$id]);if(in_array($next,['completed','cancelled'],true))q('UPDATE order_items SET progress=? WHERE order_id=?',[$next,$id]);self::history($id,$next,$notes);audit('order.status','order',$id,['status'=>$next]);});}
 static function allocate(int $item):void{module('inventory');self::expire();tx(function()use($item){$i=one('SELECT * FROM order_items WHERE id=?',[$item]);if(!$i)fail('Item not found.',404);$o=one('SELECT * FROM orders WHERE id=? FOR UPDATE',[$i['order_id']]);if(in_array($o['status'],['cancelled','completed','shipped','delivered'],true))fail('Order is not eligible for allocation.');$r=one('SELECT * FROM inventory_reservations WHERE order_item_id=? FOR UPDATE',[$item]);if($r&&$r['state']==='reserved')return;$b=one('SELECT * FROM inventory_balances WHERE variant_id=? FOR UPDATE',[$i['variant_id']]);if($b['physical']-$b['reserved']<$i['quantity'])fail('Not enough received stock.');q('UPDATE inventory_balances SET reserved=reserved+? WHERE variant_id=?',[$i['quantity'],$i['variant_id']]);q("INSERT INTO inventory_reservations(order_item_id,variant_id,quantity,state) VALUES(?,?,?,'reserved') ON DUPLICATE KEY UPDATE state='reserved',expires_at=NULL",[$item,$i['variant_id'],$i['quantity']]);self::movement((int)$i['variant_id'],(int)$i['quantity'],'preorder_allocation',(int)$o['id'],'Stock allocated');q("UPDATE order_items SET progress='stock arrived' WHERE id=?",[$item]);self::history((int)$o['id'],'stock arrived','Stock allocated',$item);});}
 static function adjust(int $vid,int $delta,string $reason):void{module('inventory');self::expire();tx(function()use($vid,$delta,$reason){$b=one('SELECT * FROM inventory_balances WHERE variant_id=? FOR UPDATE',[$vid]);if(!$b||$b['physical']+$delta<$b['reserved']||!trim($reason))fail('Adjustment cannot consume reserved stock; a reason is required.');q('UPDATE inventory_balances SET physical=physical+? WHERE variant_id=?',[$delta,$vid]);self::movement($vid,$delta,'adjustment',null,$reason);audit('stock.adjust','variant',$vid,['delta'=>$delta,'reason'=>$reason]);});}
 static function restock(int $item,int $qty,string $reason):void{module('inventory');tx(function()use($item,$qty,$reason){$i=one('SELECT * FROM order_items WHERE id=? FOR UPDATE',[$item]);$r=one("SELECT * FROM inventory_reservations WHERE order_item_id=? AND state='consumed'",[$item]);if(!$i||!$r||$qty<1||$i['restocked']+$qty>$i['quantity']||!trim($reason))fail('Return quantity exceeds fulfilled quantity or reason is missing.');q('UPDATE inventory_balances SET physical=physical+? WHERE variant_id=?',[$qty,$i['variant_id']]);q('UPDATE order_items SET restocked=restocked+? WHERE id=?',[$qty,$item]);self::movement((int)$i['variant_id'],$qty,'return',(int)$i['order_id'],$reason);});}
 static function receive(int $id):void{module('purchases');module('inventory');self::expire();tx(function()use($id){$p=one('SELECT * FROM purchase_receipts WHERE id=? FOR UPDATE',[$id]);if(!$p)fail('Purchase not found.',404);if($p['status']==='received')return;$items=all('SELECT * FROM purchase_receipt_items WHERE purchase_id=? ORDER BY variant_id',[$id]);if(!$items)fail('Purchase receipt has no lines.');foreach($items as $i){q('UPDATE inventory_balances SET physical=physical+? WHERE variant_id=?',[$i['quantity'],$i['variant_id']]);q('UPDATE product_variants SET cost=? WHERE id=?',[$i['unit_cost'],$i['variant_id']]);self::movement((int)$i['variant_id'],(int)$i['quantity'],'purchase',null,'Purchase received',$id);}q("UPDATE purchase_receipts SET status='received',received_at=NOW() WHERE id=?",[$id]);audit('purchase.received','purchase',$id);});}
 static function invoice(int $id):array{$existing=one('SELECT * FROM invoices WHERE order_id=?',[$id]);if($existing)return $existing;$o=one('SELECT * FROM orders WHERE id=?',[$id]);unset($o['access_hash'],$o['request_hash'],$o['checkout_key'],$o['internal_notes']);$items=all('SELECT * FROM order_items WHERE order_id=?',[$id]);foreach($items as &$i)unset($i['unit_cost']);unset($i);q('INSERT INTO invoices(order_id,snapshot) VALUES(?,?)',[$id,json_encode(['order'=>$o,'items'=>$items])]);$iid=(int)db()->lastInsertId();q('UPDATE invoices SET number=? WHERE id=?',['INV-'.date('Y').'-'.str_pad((string)$iid,6,'0',STR_PAD_LEFT),$iid]);return one('SELECT * FROM invoices WHERE id=?',[$iid]);}
